.darma-loader-darma-b15-kanban-card-move { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #99f6e4); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .62); position: relative; }
.darma-loader-darma-b15-kanban-card-move .darma-loader-darma-b15-kanban-card-move__col { position: absolute; top: 0; width: 30%; height: 100%; border-radius: 8px; background: color-mix(in srgb, var(--accent) 14%, transparent); }
.darma-loader-darma-b15-kanban-card-move .darma-loader-darma-b15-kanban-card-move__col:nth-of-type(1) { left: 0; }
.darma-loader-darma-b15-kanban-card-move .darma-loader-darma-b15-kanban-card-move__col:nth-of-type(2) { left: 35%; }
.darma-loader-darma-b15-kanban-card-move .darma-loader-darma-b15-kanban-card-move__col:nth-of-type(3) { left: 70%; }
.darma-loader-darma-b15-kanban-card-move .darma-loader-darma-b15-kanban-card-move__col::after { content: ''; position: absolute; left: 14%; right: 14%; top: 8%; height: 8%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 40%, transparent); }
.darma-loader-darma-b15-kanban-card-move .darma-loader-darma-b15-kanban-card-move__card { position: absolute; left: 4%; top: 26%; width: 22%; height: 26%; border-radius: 6px; background: linear-gradient(140deg, var(--accent-2), var(--accent)); box-shadow: 0 4px 10px color-mix(in srgb, #000 25%, transparent); animation: darma-loader-darma-b15-kanban-card-move-kan-move calc(var(--loader-speed, 1s) * 3.2) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes darma-loader-darma-b15-kanban-card-move-kan-move { 0%, 16% { left: 4%; top: 26%; opacity: 1; } 32%, 48% { left: 39%; top: 44%; opacity: 1; } 64%, 84% { left: 74%; top: 62%; opacity: 1; } 94%, 100% { left: 74%; top: 62%; opacity: 0; } }

